arr=(4 1 3 2)
n=${#arr[@]}
minidx() {
    local i
    idx=$1
    for (( i = $1 + 1; i < n; i++ )); do
        if (( arr[i] < arr[idx] )); then idx=$i; fi
    done
}
sort() {
    local j tmp
    for (( j = 0; j < n; j++ )); do
        minidx "$j"
        tmp=${arr[j]}
        arr[j]=${arr[idx]}
        arr[idx]=$tmp
        echo "j=$j: ${arr[*]}"
    done
}
